SELECT id AS send_id FROM email_sends
WHERE contact_id = $1 AND workflow_id = 'new_lead' AND workflow_step = 'book_inspection' AND reply_status = 'waiting'
ORDER BY sent_at DESC LIMIT 1;

SELECT COALESCE(
  (SELECT calendar_id FROM calendar_integrations WHERE owner_user_id = $1 AND is_active = true LIMIT 1),
  (SELECT calendar_id FROM calendar_integrations WHERE is_active = true ORDER BY id LIMIT 1)
) AS calendar_id;

